    setActiveTab(tab);
  }, []);

  if (loading) {
    return <div className="p-8">Loading comparison...</div>;
  }

  return (
    <div className="p-8">
      <h1 className="text-3xl font-bold mb-6">Product Comparison</h1>

      <div className="mb-8 space-x-2">
        <button
          onClick={() => handleTabChange('basic')}
          className={`px-4 py-2 rounded ${
            activeTab === 'basic' 
