              ? 'bg-blue-500 text-white' 
              : 'bg-gray-200 text-black'
          }`}
        >
          Advanced
        </button>
      </div>

      {activeTab === 'basic' && (
        <CompareView products={basicProducts} />
      )}

      {activeTab === 'advanced' && (
        <CompareView products={advancedProducts} />
      )}
    </div>
  );
}
