# React Performance Optimization

## Overview
Techniques to optimize React component rendering and prevent performance bottlenecks.

## Core Optimization Techniques

### 1. React.memo
Prevents unnecessary re-renders when props haven't changed.

```typescript
// Without memo - re-renders on every parent render
export function ProductCard({ product }: Props) {
  return <div>{product.name}</div>;
}

// With memo - only re-renders when props change
export const ProductCard = React.memo(function ProductCard({ product }: Props) {
  return <div>{product.name}</div>;
});
```

### 2. useMemo Hook
Memoizes expensive calculations.

```typescript
function ProductList({ products, filter }: Props) {
  // Bad: Recalculates on every render
  const filtered = products.filter(p => p.name.includes(filter));

  // Good: Only recalculates when dependencies change
  const filtered = useMemo(
    () => products.filter(p => p.name.includes(filter)),
    [products, filter]
  );

  return <div>{/* render */}</div>;
}
```

### 3. useCallback Hook
Memoizes function references.

```typescript
function Parent() {
  const [count, setCount] = useState(0);

  // Bad: New function on every render
  const handleClick = (id: string) => {
    console.log(id);
  };

  // Good: Memoized function
  const handleClick = useCallback((id: string) => {
    console.log(id);
  }, []); // No dependencies = never changes

  return <Child onClick={handleClick} />;
}
```

## Common Performance Pitfalls

### 1. Expensive Calculations in Render
```typescript
// Bad: Runs on every render
function Component({ products }: Props) {
  const sorted = products.sort((a, b) => b.price - a.price);
  const grouped = groupBy(sorted, 'category');
  const stats = calculateStats(grouped);

  return <div>{/* render */}</div>;
}

// Good: Memoized calculations
function Component({ products }: Props) {
  const sorted = useMemo(
    () => products.sort((a, b) => b.price - a.price),
    [products]
  );

  const grouped = useMemo(
    () => groupBy(sorted, 'category'),
    [sorted]
  );

  const stats = useMemo(
    () => calculateStats(grouped),
    [grouped]
  );

  return <div>{/* render */}</div>;
}
```

### 2. Function Calls in Render
```typescript
// Bad: Called for each item on every render
function List({ items, reviews }: Props) {
  return (
    <div>
      {items.map(item => (
        <Item 
          key={item.id}
          reviewCount={getReviewCount(item.id, reviews)} // Expensive!
        />
      ))}
    </div>
  );
}

// Good: Pre-calculate once
function List({ items, reviews }: Props) {
  const reviewCounts = useMemo(
    () => {
      const counts: Record<string, number> = {};
      reviews.forEach(r => {
        counts[r.productId] = (counts[r.productId] || 0) + 1;
      });
      return counts;
    },
    [reviews]
  );

  return (
    <div>
      {items.map(item => (
        <Item 
          key={item.id}
          reviewCount={reviewCounts[item.id] || 0}
        />
      ))}
    </div>
  );
}
```

### 3. Inline Object/Array Creation
```typescript
// Bad: New object on every render
function Component() {
  return <Child style={{ color: 'red' }} />;
}

// Good: Memoized or constant
const STYLE = { color: 'red' };
function Component() {
  return <Child style={STYLE} />;
}
```

## Component Optimization Patterns

### Memoize Child Components
```typescript
// Child component
export const ProductCard = React.memo(function ProductCard({ product, onAdd }: Props) {
  return <div>{/* render */}</div>;
});

// Parent component
function ProductList({ products }: Props) {
  const handleAdd = useCallback((id: string) => {
    // handle add
  }, []);

  return (
    <div>
      {products.map(p => (
        <ProductCard key={p.id} product={p} onAdd={handleAdd} />
      ))}
    </div>
  );
}
```

### Split Components
```typescript
// Bad: Entire component re-renders on filter change
function ProductPage() {
  const [filter, setFilter] = useState('');
  const [products] = useState(expensiveProducts);

  return (
    <div>
      <input value={filter} onChange={e => setFilter(e.target.value)} />
      <ExpensiveList products={products} />
    </div>
  );
}

// Good: Split into separate components
function ProductPage() {
  const [products] = useState(expensiveProducts);
  return (
    <div>
      <FilterInput />
      <ExpensiveList products={products} />
    </div>
  );
}
```

