# Bundle Size Optimization

## Overview
Strategies to reduce JavaScript bundle size for faster load times and better performance.

## Common Bundle Size Issues

### 1. Lodash Import Optimization

**Problem:** Importing entire lodash library
```typescript
// Bad: Imports entire lodash (~70KB)
import { groupBy, sortBy, meanBy } from 'lodash';
import _ from 'lodash';
```

**Solution:** Import specific functions
```typescript
// Good: Import only what you need
import groupBy from 'lodash/groupBy';
import sortBy from 'lodash/sortBy';
import meanBy from 'lodash/meanBy';

// Or use lodash-es for better tree-shaking
import { groupBy, sortBy, meanBy } from 'lodash-es';
```

**Better:** Use native JavaScript when possible
```typescript
// Instead of lodash groupBy
const grouped = items.reduce((acc, item) => {
  const key = item.category;
  if (!acc[key]) acc[key] = [];
  acc[key].push(item);
  return acc;
}, {});

// Instead of lodash sortBy
const sorted = [...items].sort((a, b) => a.price - b.price);

// Instead of lodash meanBy
const average = items.reduce((sum, item) => sum + item.price, 0) / items.length;
```

### 2. Math Libraries

**Problem:** Large math libraries for simple operations
```typescript
// Bad: mathjs is ~500KB
import { mean, std, median, variance } from 'mathjs';
```

**Solution:** Implement simple statistics yourself
```typescript
// Good: Lightweight custom functions
function mean(numbers: number[]): number {
  return numbers.reduce((sum, n) => sum + n, 0) / numbers.length;
}

function median(numbers: number[]): number {
  const sorted = [...numbers].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

function variance(numbers: number[]): number {
  const avg = mean(numbers);
  return mean(numbers.map(n => Math.pow(n - avg, 2)));
}

function std(numbers: number[]): number {
  return Math.sqrt(variance(numbers));
}

function quantile(numbers: number[], q: number): number {
  const sorted = [...numbers].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;

  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}
```

### 3. Date Libraries

**Problem:** Moment.js is large (~70KB)
```typescript
import moment from 'moment';
```

**Solution:** Use native Intl API or date-fns
```typescript
// Native Intl API
const formatted = new Intl.DateTimeFormat('en-US').format(date);

// Or date-fns (modular)
import { format } from 'date-fns';
const formatted = format(date, 'yyyy-MM-dd');
```

## Dynamic Imports

### Code Splitting
```typescript
// Bad: Loads heavy component immediately
import HeavyChart from './HeavyChart';

function Page() {
  return <HeavyChart data={data} />;
}

// Good: Load only when needed
import dynamic from 'next/dynamic';

const HeavyChart = dynamic(() => import('./HeavyChart'), {
  loading: () => <div>Loading chart...</div>,
});

function Page() {
  return <HeavyChart data={data} />;
}
```

### Conditional Loading
```typescript
// Load heavy library only when needed
function Component() {
  const [showAdvanced, setShowAdvanced] = useState(false);

  const handleAdvanced = async () => {
    const { processData } = await import('./heavy-processor');
    const result = processData(data);
    setShowAdvanced(true);
  };

  return <div>{/* render */}</div>;
}
```

