      <h1>Products</h1>
      <Suspense fallback={<div>Loading products...</div>}>
        <ProductList />
      </Suspense>
      <Suspense fallback={<div>Loading reviews...</div>}>
        <ReviewList />
      </Suspense>
    </div>
  );
}

async function ProductList() {
  const products = await fetchProducts();
  return <div>{/* render */}</div>;
}
