# React Hooks for Performance

## Overview
Using React hooks effectively to optimize component performance and prevent unnecessary renders.

## useMemo Hook

### Basic Usage
```typescript
import { useMemo } from 'react';

function Component({ items, filter }: Props) {
  // Memoize expensive calculation
  const filteredItems = useMemo(
    () => items.filter(item => item.name.includes(filter)),
    [items, filter] // Recalculate only when these change
  );

  return <div>{filteredItems.length} items</div>;
}
```

### When to Use useMemo

**Use for:**
- Expensive calculations (sorting, filtering large arrays)
- Complex transformations
- Creating objects/arrays passed as props
- Statistical calculations

**Don't use for:**
- Simple arithmetic (a + b)
- Single property access
- String concatenation
- Premature optimization

### Multiple Dependent Calculations
```typescript
function AnalyticsPanel({ data }: Props) {
  // Calculate in stages
  const filtered = useMemo(
    () => data.filter(d => d.isValid),
    [data]
  );

  const sorted = useMemo(
    () => [...filtered].sort((a, b) => b.value - a.value),
    [filtered]
  );

  const stats = useMemo(
    () => ({
      mean: sorted.reduce((sum, d) => sum + d.value, 0) / sorted.length,
      max: sorted[0]?.value || 0,
      min: sorted[sorted.length - 1]?.value || 0,
    }),
    [sorted]
  );

  return <div>{/* render */}</div>;
}
```

## useCallback Hook

### Basic Usage
```typescript
import { useCallback } from 'react';

function Parent() {
  const [items, setItems] = useState([]);

  // Memoize callback
  const handleAdd = useCallback((id: string) => {
    setItems(prev => [...prev, id]);
  }, []); // No dependencies - function never changes

  return <Child onAdd={handleAdd} />;
}
```

### With Dependencies
```typescript
function SearchComponent({ category }: Props) {
  const [query, setQuery] = useState('');

  // Recreate when category changes
  const handleSearch = useCallback((term: string) => {
    fetch(`/api/search?q=${term}&category=${category}`);
  }, [category]); // Recreate when category changes

  return <SearchInput onSearch={handleSearch} />;
}
```

### Functional Updates
```typescript
function Counter() {
  const [count, setCount] = useState(0);

  // Use functional update to avoid count dependency
  const increment = useCallback(() => {
    setCount(c => c + 1); // No dependency on count
  }, []); // Stable reference

  return <button onClick={increment}>Count: {count}</button>;
}
```

## Common Patterns

### Pre-computing Lookup Tables
```typescript
function ProductList({ products, reviews }: Props) {
  // Bad: O(n*m) complexity on every render
  // {products.map(p => getReviewCount(p.id, reviews))}

  // Good: O(n) once, then O(1) lookups
  const reviewCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    reviews.forEach(review => {
      counts[review.productId] = (counts[review.productId] || 0) + 1;
    });
    return counts;
  }, [reviews]);

  return (
    <div>
      {products.map(product => (
        <ProductCard
          key={product.id}
          product={product}
          reviewCount={reviewCounts[product.id] || 0}
        />
      ))}
    </div>
  );
}
```

### Memoizing Component Props
```typescript
function Parent() {
  const [count, setCount] = useState(0);

  // Memoize callback
  const handleClick = useCallback(() => {
    setCount(c => c + 1);
  }, []);

  // Memoize config object
  const config = useMemo(
    () => ({ theme: 'dark', size: 'large' }),
    []
  );

  return <MemoizedChild onClick={handleClick} config={config} />;
}

const MemoizedChild = React.memo(Child);
```

### Debouncing with useMemo
```typescript
import { useMemo, useState } from 'react';
import debounce from 'lodash/debounce';

function SearchInput() {
  const [query, setQuery] = useState('');

  // Memoize debounced function
  const debouncedSearch = useMemo(
    () => debounce((value: string) => {
      fetch(`/api/search?q=${value}`);
    }, 300),
    []
  );

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setQuery(value);
    debouncedSearch(value);
  };

  return <input value={query} onChange={handleChange} />;
}
```

## Anti-Patterns to Avoid

### Over-Memoization
```typescript
// Bad: Unnecessary memoization
const sum = useMemo(() => a + b, [a, b]); // Overkill
const text = useMemo(() => `Hello ${name}`, [name]); // Too simple

// Good: Just calculate
const sum = a + b;
const text = `Hello ${name}`;
```

### Missing Dependencies
```typescript
// Bad: Missing dependencies
const filtered = useMemo(
  () => items.filter(item => item.type === selectedType),
  [items] // Missing selectedType!
);

// Good: All dependencies included
const filtered = useMemo(
  () => items.filter(item => item.type === selectedType),
  [items, selectedType]
);
```

### Memoizing Everything
```typescript
// Bad: Premature optimization
function SimpleComponent({ name }: Props) {
  const greeting = useMemo(() => `Hello, ${name}`, [name]);
  const handleClick = useCallback(() => console.log('hi'), []);

  return <button onClick={handleClick}>{greeting}</button>;
}

// Good: Keep it simple
function SimpleComponent({ name }: Props) {
  return <button onClick={() => console.log('hi')}>Hello, {name}</button>;
}
```

## Combining with React.memo

```typescript
// Memoized component
const ProductCard = React.memo(function ProductCard({ 
  product, 
  onAdd 
}: Props) {
  return <div>{/* render */}</div>;
});

// Parent with memoized callback
function ProductList({ products }: Props) {
  const handleAdd = useCallback((id: string) => {
    // handle add
  }, []);

  return (
    <div>
      {products.map(p => (
        <ProductCard 
          key={p.id} 
          product={p} 
          onAdd={handleAdd} // Stable reference
        />
      ))}
    </div>
  );
}
```

