### 3. React Performance Optimization 🚀

#### Issue: ProductCard Re-renders Unnecessarily
**File:** `src/components/ProductCard.tsx`

**Before:**
```typescript
export function ProductCard({ product, reviewCount, onAddToCart, isInCart }: Props) {
  // Re-renders whenever parent re-renders
}
```

**After:**
```typescript
function ProductCard({ product, reviewCount, onAddToCart, isInCart }: Props) {
  // Component logic
}

export default React.memo(ProductCard);
```
- Only re-renders when props actually change
- **Prevents unnecessary re-renders**

#### Issue: Expensive Calculations on Every Render
**File:** `src/components/ProductList.tsx`

**Before:**
```typescript
function ProductList({ products, reviews }: Props) {
  // Recalculated on EVERY render
  const filteredProducts = products
    .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
    .filter(p => p.inStock)
    .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);

  const getReviewCount = (productId: string) => {
    // Called for EACH product on EVERY render - O(n*m) complexity!
    return reviews.filter(r => r.productId === productId).length;
  };
}
```

**After:**
```typescript
function ProductList({ products, reviews }: Props) {
  // Pre-compute review counts once - O(n) complexity
  const reviewCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    reviews.forEach(review => {
      counts[review.productId] = (counts[review.productId] || 0) + 1;
    });
    return counts;
  }, [reviews]);

  // Memoize expensive filtering and sorting
  const filteredProducts = useMemo(() => {
    return products
      .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
      .filter(p => p.inStock)
      .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);
  }, [products, filter, sortBy]);

  // Memoize callback to prevent ProductCard re-renders
  const handleAddToCart = useCallback((productId: string) => {
    setCart(prev => [...prev, productId]);
  }, []);
}
```
- **O(n*m) → O(1)** for review count lookups
- Filtering/sorting only when dependencies change
- Stable callback reference prevents child re-renders

#### Issue: Compare Page Components Not Memoized
**File:** `src/app/compare/page.tsx`

**Before:**
```typescript
function ComparisonTable({ products }: { products: Product[] }) {
  // All calculations run on every render
  const sorted = sortBy(products, ['price']);
  const avgPrice = meanBy(products, 'price');
  const totalReviews = sumBy(products, 'reviews');
  // ... more calculations
}

function AdvancedAnalysis({ products }: { products: Product[] }) {
  // Expensive statistical calculations on every render
  const prices = products.map(p => p.price);
  const priceStats = {
    mean: mean(prices),
    median: median(prices),
    std: std(prices),
    variance: variance(prices),
    // ... more stats
  };
}
```

**After:**
```typescript
const ComparisonTable = React.memo(function ComparisonTable({ products }) {
  // Memoize each calculation
  const sorted = useMemo(
    () => [...products].sort((a, b) => a.price - b.price),
    [products]
  );

  const avgPrice = useMemo(
    () => products.reduce((sum, p) => sum + p.price, 0) / products.length,
    [products]
  );

  // ... all calculations memoized
});

const AdvancedAnalysis = React.memo(function AdvancedAnalysis({ products }) {
  // Memoize all statistical calculations
  const priceStats = useMemo(() => {
    const prices = products.map(p => p.price);
    return {
      mean: mean(prices),
      median: median(prices),
      std: std(prices),
      variance: variance(prices),
      q1: quantile(prices, 0.25),
      q3: quantile(prices, 0.75),
    };
  }, [products]);

  // ... all stats memoized
});
```
- Components wrapped in React.memo
- All expensive calculations memoized
- **Only recalculates when products change**

